func get_validators_custody_requirement*(cfg: RuntimeConfig, total_node_balance: Gwei): uint64 =
  let count = total_node_balance div cfg.BALANCE_PER_ADDITIONAL_CUSTODY_GROUP
  min(max(count.uint64, cfg.VALIDATOR_CUSTODY_REQUIREMENT), cfg.NUMBER_OF_CUSTODY_GROUPS.uint64)

func get_data_column_sidecars*(signed_beacon_block: fulu.SignedBeaconBlock, cellsAndProofs: seq[CellsAndProofs]): seq[fulu.DataColumnSidecar] =
  var sidecars = newSeqOfCap[fulu.DataColumnSidecar](CELLS_PER_EXT_BLOB)
  for column_index in 0..<NUMBER_OF_COLUMNS:
    var sidecar = fulu.DataColumnSidecar(
      index: ColumnIndex(column_index),
      ...)
    sidecars.add(sidecar)
  sidecars
